        'tool_call': {
          'id': 'c1-$i',
          'name': 'bash',
          'arguments': {
            'command': 'sleep ${_waveOneSleepBase + i} && echo p539-wave1-$i',
            'background': true,
          },
        },
      },
  ],
  [
    {'text': _replyOne},
  ],
  [
    {'text': 'launching the second wave'},
    for (var i = 1; i <= 6; i++)
      {
        'tool_call': {
          'id': 'c2-$i',
          'name': 'bash',
          'arguments': {
            'command': 'sleep 300 && echo p539-wave2-$i',
            'background': true,
