+          t.buffer.lines[t.buffer.scrollBack + 4].getText();
+
+      expect(lineOf(written), isNot(lineOf(erased)));
+      expect(
+        lineOf(written).trimRight(),
+        lineOf(erased).trimRight(),
+      );
+    });
